/**
 * ======================================================================
 * 【基本说明】：
 * MobileIMSDK-Web版服务端的错误码封装类，目的仅是为了方便错误码的使用而已。
 * 错误码详见code.js文件中的定义。
 * ======================================================================
 */

"use strict";

function ErrorCode(code, msg) {
    this.code = code;
    this.msg = msg;
}

ErrorCode.prototype.toString = function() {
    return 'code='+this.code+", msg="+this.msg;
};

// 如果不是导出属性，则exports.ErrorCode = ErrorCode在代码里用时new会报
// “TypeError:ErrorCode在代码里用时new会报 is not a function”
// “module.exports = ErrorCode”方式导出的是一个class！
// 另：存在module.exports的情况下就不能再exports.XXXX这样的常量了，这也是为何
// 一个ErrorCode类拆成现在的3个文件的原因，这就是NodeJS面向对象的繁琐之处！
module.exports = ErrorCode;

